"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8406],{2173:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"","params":[{"name":"options","desc":"","lua_type":"SightOptions?"}],"returns":[{"desc":"","lua_type":"Sight"}],"function_type":"static","errors":[{"lua_type":"\\"unknown option\\"","desc":"A key not in `SightOptions`."},{"lua_type":"\\"Range must be zero or more\\"","desc":""}],"source":{"line":133,"path":"lib/Senses/Sight.luau"}},{"name":"Tick","desc":"Looks, and writes the keys listed above to `agent.Blackboard`.","params":[{"name":"self","desc":"","lua_type":"Sight"},{"name":"agent","desc":"","lua_type":"Agent"},{"name":"deltaTime","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":161,"path":"lib/Senses/Sight.luau"}},{"name":"Destroy","desc":"Nothing to release; present so the sense satisfies [Types.Sense] and any cleanup helper.","params":[{"name":"self","desc":"","lua_type":"Sight"}],"returns":[],"function_type":"static","source":{"line":263,"path":"lib/Senses/Sight.luau"}},{"name":"Configure","desc":"Changes options after construction, for difficulty and pacing: a director widening the cone\\nor shortening the memory mid-round. The same rules as `new` apply.","params":[{"name":"self","desc":"","lua_type":"Sight"},{"name":"patch","desc":"The options to change; the rest keep their values.","lua_type":"SightOptions"}],"returns":[],"function_type":"static","errors":[{"lua_type":"\\"unknown option\\"","desc":""}],"source":{"line":275,"path":"lib/Senses/Sight.luau"}}],"properties":[],"types":[{"name":"SightOptions","desc":"","fields":[{"name":"Range","lua_type":"number?","desc":"Studs the agent can see. Default `40`."},{"name":"FieldOfView","lua_type":"number?","desc":"The full angle of the view cone, in degrees. Default `120`."},{"name":"EyeOffset","lua_type":"Vector3?","desc":"Added to the entity\'s pivot to get the eye. Default `Vector3.zero`."},{"name":"Memory","lua_type":"number?","desc":"Seconds `SeenPosition` and `SeenAt` outlive the last sighting. Default `3`."},{"name":"Targets","lua_type":"((agent: Agent) -> { BasePart })?","desc":"What to look for. Default [Perception.AliveRoots], every alive player\'s root."},{"name":"Ignore","lua_type":"((agent: Agent) -> { Instance })?","desc":"What the sight ray passes through. Default [Perception.IgnoreList], the agent\'s entity."},{"name":"Visibility","lua_type":"((agent: Agent, target: BasePart) -> number)?","desc":"How visible a target is, `0` to `1` (or more): the range is multiplied by it, so `0` is invisible and `0.5` is seen at half the distance. Pass `function(_, root) return VluxyAI.Perception.LightAt(root.Position) end` for darkness. Default: everything `1`."},{"name":"SeeThrough","lua_type":"((part: BasePart) -> boolean)?","desc":"Parts the sight ray looks past, such as [Perception.Transparent]. Default: everything blocks."},{"name":"PerTarget","lua_type":"boolean?","desc":"Also write `SeenMemory`, the last position and time of every target seen within `Memory` seconds, so an enemy remembers where each of several players went. Default `false`."},{"name":"Predict","lua_type":"number?","desc":"Seconds of the target\'s last velocity to carry `PredictedPosition` forward after losing sight, capped. `0` turns prediction off. Default `2`."},{"name":"Prefix","lua_type":"string?","desc":"Prepended to every key this sense writes, so two instances can coexist. Default `\\"\\"`."}],"source":{"line":71,"path":"lib/Senses/Sight.luau"}}],"name":"Sight","desc":"A [Types.Sense] that writes what the agent can see. A target is seen when it is within `Range`,\\ninside the `FieldOfView` cone around the entity\'s look direction, and a ray from the eye to it\\nhits nothing but the target\'s own model.\\n\\nWrites `SeenTargets`, `SeenTarget`, `SeenDistance`, `SeenVisibility`, `SeenPosition` and\\n`SeenAt`. The last two are memory: they outlive the sighting by `Memory` seconds so a state\\ncan head to where the target was. Distances are `math.huge` when there is nothing to measure.\\n\\nFor a horror game: `Visibility` scales the range per target, so darkness and a lit flashlight\\nare one function ([Perception.LightAt] is the ready-made one); `SeeThrough` lets the ray pass\\nglass ([Perception.Transparent]); and a player hidden with `AI_HIDDEN` is not a target at all.","source":{"line":125,"path":"lib/Senses/Sight.luau"}}')}}]);